ALTER TABLE "person_identifiers" ADD CONSTRAINT "person_identifiers_blind_index_v1_check" CHECK ("person_identifiers"."blind_index_version" IS NULL OR ("person_identifiers"."blind_index_version" = 1 AND (("person_identifiers"."encrypted_raw_value" IS NOT NULL AND "person_identifiers"."blind_index" IS NOT NULL AND "person_identifiers"."normalized_value" IS NULL AND "person_identifiers"."blind_index" ~ '^[0-9a-f]{64}$') OR ("person_identifiers"."encrypted_raw_value" IS NULL AND "person_identifiers"."blind_index" IS NULL AND "person_identifiers"."normalized_value" IS NOT NULL))));